// === Tab: mySketch ===
/**
 * PRIME_MATTER // PHYSARUM_FLUX
 * Trend: Bio-Mimicry & Swarm Intelligence (The Blob).
 * * CONCEPT:
 * Simulating Physarum Polycephalum behavior.
 * Agents deposit pheromones, sense the gradient, and steer towards concentration.
 * Creates emergent transport networks similar to biological veins or city maps.
 *
 * * TECH:
 * - Agent-based modeling combined with grid-based diffusion.
 * - Optimized for performance (Lookup Tables).
 *
 * * CONTROLS:
 * - NO ACTION: Watch the network self-organize.
 * - MOUSE DRAG: Repel agents (Disrupt the network).
 */

let agents = [];
let numAgents = 2000; 
let sensorAngle = 45; // Angle de vision des agents
let sensorDist = 10;  // Distance de vision
let turnSpeed = 0.2;  // Vitesse de rotation

// Grille des phéromones (Trail Map)
// On utilise un tableau simple pour la performance
let trail = [];
let widthMap, heightMap;
let resolution = 2; // Facteur de réduction pour la map (Optimisation)

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  background(0);
  noSmooth();

  // Dimensions de la carte de phéromones
  widthMap = floor(width / resolution);
  heightMap = floor(height / resolution);

  // Initialisation de la grille vide
  for (let i = 0; i < widthMap * heightMap; i++) {
    trail[i] = 0;
  }

  // Création du chaos initial (Cercle ou Random)
  for (let i = 0; i < numAgents; i++) {
    // Départ en cercle pour une explosion organique
    let angle = random(TWO_PI);
    let r = random(10);
    agents.push(new Agent(widthMap/2 + cos(angle)*r, heightMap/2 + sin(angle)*r));
  }
}

function draw() {
  background(0, 0, 0, 10); // Fade très lent pour garder les structures

  // 1. UPDATE & DRAW AGENTS
  loadPixels();

  // On prépare l'accès aux pixels de l'écran (pour l'affichage)
  // Et on lit/écrit dans notre tableau 'trail' (pour la logique)

  for (let agent of agents) {
    agent.sense(); // Sentir l'environnement
    agent.update(); // Bouger

    // Déposer des phéromones
    let x = floor(agent.x);
    let y = floor(agent.y);
    if (x >= 0 && x < widthMap && y >= 0 && y < heightMap) {
      trail[x + y * widthMap] = 255; // Intensité max

      // Dessin direct sur l'écran (Pixel blanc)
      // On multiplie par la résolution pour l'affichage
      let px = x * resolution;
      let py = y * resolution;
      set(px, py, color(255)); // Optimisation possible via pixels[] direct mais set() est plus lisible ici
    }
  }

  // 2. DIFFUSION & DECAY (Le secret du look "Veines")
  // Les phéromones s'étalent et disparaissent
  // C'est lourd à calculer, donc on le fait un peu "sale" mais rapide
  // On ne traite qu'une partie de la grille ou on simplifie

  // Simulation simplifiée du Decay (tout le monde perd de l'intensité)
  for (let i = 0; i < trail.length; i++) {
     trail[i] *= 0.95; // Decay rate (Vitesse de disparition)
  }

  updatePixels();

  // 3. INTERACTION (Inhibiteur)
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
    fill(255, 0, 0, 50);
    noStroke();
    ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 100, 100);
  }

  drawUI();
}

class Agent {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.angle = random(TWO_PI);
    this.speed = 1;
  }

  sense() {
    // Sentir 3 points devant (Gauche, Tout droit, Droite)
    let sensorLeft = this.getTrailValue(this.angle - sensorAngle);
    let sensorFront = this.getTrailValue(this.angle);
    let sensorRight = this.getTrailValue(this.angle + sensorAngle);

    // Logique de direction (Steering)
    if (sensorFront > sensorLeft && sensorFront > sensorRight) {
      // Continuer tout droit
    } else if (sensorFront < sensorLeft && sensorFront < sensorRight) {
      // Tourner au hasard
      this.angle += (random() - 0.5) * 2 * turnSpeed;
    } else if (sensorRight > sensorLeft) {
      this.angle += turnSpeed;
    } else if (sensorLeft > sensorRight) {
      this.angle -= turnSpeed;
    }

    // Interaction Souris (Répulsion)
    // On convertit les coords souris vers coords map
    let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / resolution;
    let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / resolution;
    let d = dist(this.x, this.y, mx, my);
    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && d < 50 / resolution) {
      let angleToMouse = atan2(my - this.y, mx - this.x);
      this.angle = angleToMouse + PI; // Fuir à l'opposé
    }
  }

  getTrailValue(angle) {
    // Calculer la position du capteur
    let sx = this.x + cos(angle) * sensorDist;
    let sy = this.y + sin(angle) * sensorDist;

    // Coordonnées entières
    let ix = floor(sx);
    let iy = floor(sy);

    // Vérifier les bords (Tore ou Mur)
    if (ix < 0 || ix >= widthMap || iy < 0 || iy >= heightMap) return 0;

    return trail[ix + iy * widthMap];
  }

  update() {
    // Avancer
    this.x += cos(this.angle) * this.speed;
    this.y += sin(this.angle) * this.speed;

    // Bords (Rebond ou Traversée)
    if (this.x < 0) this.x = widthMap - 1;
    if (this.x >= widthMap) this.x = 0;
    if (this.y < 0) this.y = heightMap - 1;
    if (this.y >= heightMap) this.y = 0;
  }
}

function drawUI() {
  fill(255);
  noStroke();
  textFont('Courier New');
  textSize(12);
  textAlign(LEFT, TOP);

  text("PRIME_MATTER // PHYSARUM_FLUX", 20, 20);
  text("AGENTS: " + numAgents, 20, 35);
  text("EMERGENCE_STATUS: " + (frameCount > 200 ? "STABLE" : "EVOLVING"), 20, 50);
}

function windowResized() {
  setup(); // Reset complet nécessaire car la grille change
}

